SELECT AVG(CarsData.WEIGHT) AS AvgWeight, AVG(CarsData.YEAR) AS AvgYear
FROM CarsData
GROUP BY CarsData.YEAR;

SELECT COUNT(*) AS airline_count
FROM airlines
WHERE Country = 'USA';

SELECT DISTINCT s.Location, COUNT(s.Shop_ID) AS Shop_Count
FROM shop s
GROUP BY s.Location;

SELECT COUNT(DISTINCT s.Location) AS Store_Count
FROM shop s
GROUP BY s.Location;

SELECT DISTINCT t.Name
FROM teacher t
WHERE t.Hometown NOT LIKE 'Little Lever Urban District';

SELECT DISTINCT t.Name
FROM teacher t
WHERE t.Age IN (32, 33);

SELECT AVG(loser_age) AS avg_losers, AVG(winner_age) AS avg_winners
FROM matches
GROUP BY loser_age, winner_age;

SELECT MAX(death.id) as max_death_toll, MIN(death.id) as min_death_toll
FROM death
GROUP BY death.id;

SELECT DISTINCT d.department_name, d.department_description
FROM Departments d
WHERE d.department_name LIKE '%computer%';

SELECT COUNT(DISTINCT p.People_ID) AS Different_Nationalities
FROM people p
JOIN poker_player p2 ON p.People_ID = p2.People_ID;

SELECT COUNT(*) as RepublicCount
FROM country
WHERE GovernmentForm = 'REPUBLIC';

SELECT COUNT(*) AS NumberOfNations
FROM country
WHERE CountryCode IN ('EN', 'NL');

SELECT DISTINCT c.Name
FROM conductor c
WHERE c.Nationality != 'USA';

SELECT COUNT(DISTINCT t.dog_id)
FROM Treatments t
JOIN Dogs d ON t.dog_id = d.dog_id;
